// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";

import ExternalStylesExample from "./variants/external-styles";

const ExternalStylesSource = "import { CSPProvider } from \"@/registry/erbium/ui/csp-provider\";\nimport { ScrollArea } from \"@/registry/erbium/ui/scroll-area\";\nimport type * as React from \"react\";\n\nconst Example = (args: React.ComponentProps<typeof CSPProvider>) => (\n  <CSPProvider {...args}>\n    <ScrollArea className=\"h-40 w-72\" aria-label=\"CSP provider example\">\n      {Array.from({ length: 12 }, (_, index) => (\n        <p key={index} className=\"p-3\">\n          Scrollable item {index + 1}\n        </p>\n      ))}\n    </ScrollArea>\n  </CSPProvider>\n);\n\nexport default Example;\n";

import ShowcaseExample from "./variants/showcase";

const ShowcaseSource = "import ShowcaseDemo from \"../examples/csp-provider-demo\";\n\nconst Example = () => <ShowcaseDemo />;\n\nexport default Example;\n";

const meta = {
  title: "UI/CSP Provider",
  component: CSPProvider,
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "Configures inline style and script tags rendered by Base UI components. Import from `@/registry/erbium/ui/csp-provider`.\n\nWrap your application with `<CSPProvider nonce={nonceFromServer}>` when your CSP requires a nonce. Generate a fresh nonce on the server for each response and include the same value in the CSP header. The provider does not configure the header or authorize inline style attributes.\n\nAlternatively, use `disableStyleElements` with Erbium's global stylesheet, which includes Base UI's scrollbar-hiding rules. Storybook and the docs previews use this configuration. This option does not disable inline scripts; opt-in scripts still require a nonce under a strict CSP.\n\nSee [Base UI CSP Provider](https://base-ui.com/react/utils/csp-provider) for server configuration and limitations.",
      },
    },
  },
} satisfies Meta<typeof CSPProvider>;

export default { ...meta,  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const ExternalStyles: Story = {
  args: { disableStyleElements: true },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: ExternalStylesSource },
    },
  },
  render: ExternalStylesExample,
};

export const Showcase: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: ShowcaseSource },
    },
  },
  render: ShowcaseExample,
};

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { ScrollArea } from "@/registry/erbium/ui/scroll-area";
export default function Demo() {
  return (
    <CSPProvider disableStyleElements>
      <ScrollArea className="h-40 w-72" aria-label="Scrollable example">
        {Array.from({ length: 12 }, (_, index) => (
          <p key={index} className="p-3">
            Scrollable item {index + 1}
          </p>
        ))}
      </ScrollArea>
    </CSPProvider>
  );
}

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { ScrollArea } from "@/registry/erbium/ui/scroll-area";
import type * as React from "react";

const Example = (args: React.ComponentProps<typeof CSPProvider>) => (
  <CSPProvider {...args}>
    <ScrollArea className="h-40 w-72" aria-label="CSP provider example">
      {Array.from({ length: 12 }, (_, index) => (
        <p key={index} className="p-3">
          Scrollable item {index + 1}
        </p>
      ))}
    </ScrollArea>
  </CSPProvider>
);

export default Example;

import ShowcaseDemo from "../examples/csp-provider-demo";

const Example = () => <ShowcaseDemo />;

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div className="component-preview relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout">
      {children}
    </div>
  );
}
